  }) {
    return SkippedDayCancellationCompanion(
      skippedDayId: skippedDayId ?? this.skippedDayId,
      reason: reason ?? this.reason,
      createdAt: createdAt ?? this.createdAt,
      rowid: rowid ?? this.rowid,
